    array('id' => 'I11', 'type' => 'Upper-case field name and value', 'search' => 'Title:Sculpture', 'core' => 'Field names compare case-insensitively in MySQL; the value is normalised.', 'where' => 'include/do_search_keywords.php:105'),
    array('id' => 'I12', 'type' => 'Dropdown value from the advanced form', 'search' => '"source:igital Camer"', 'core' => 'search_form_to_search_query has a branch that strips the first and last characters of a dropdown value with spaces; dropdowns post node refs instead, so the branch is unreachable and this is only what it would send for "Digital Camera".', 'where' => 'include/search_functions.php:290'),

    array('group' => 'J', 'title' => 'Strings as the advanced search page assembles them', 'intro' => 'search_form_to_search_query() builds one string in a fixed order: the date dropdowns, the words of the all-fields box, a !list prefix for the resource IDs box, the full-text box, one term per word per field box (a quoted phrase stays quoted around the whole term), the ticked options and dropdown choices as @@ tokens, and last a !properties prefix joined with " ,". A posted special search such as !contributions is prefixed with a comma and no space. Not sent as text: a checkbox list with every option ticked (omitted), the Featured Collections type (a collections search) and the access selector (a PHP argument only). Fields with a verbatim-keyword regex keep their value unsplit; none is configured on the test system.'),
    array('id' => 'J1', 'type' => 'Resource IDs, words, a field, nodes, type and state', 'search' => '!list2181:3879:4093 sculpture, landscape, title:sculpture, @@389@@388', 'restypes' => '5', 'archive' => '0', 'core' => 'The !list prefix, then after a space the terms the form added: the listed refs that also match everything else.', 'where' => 'include/search_functions.php:239, include/do_search.php:126'),
    array('id' => 'J2', 'type' => 'The same with a property filled in', 'search' => '!propertiesfext:jpg ,!list2181:3879:4093 sculpture, landscape, title:sculpture, @@389@@388', 'restypes' => '5', 'archive' => '0', 'core' => 'The !properties prefix is now the special search and !list a second one, which the keyword stage skips: the resource IDs box is ignored whenever a property is set.', 'where' => 'include/search_functions.php:406, include/do_search_keywords.php:88'),
    array('id' => 'J3', 'type' => 'Posted special search prefix', 'search' => '!contributions9,sculpture', 'core' => 'The form joins them with a comma and no space, so the term is dropped (I1): the contributions alone.', 'where' => 'include/search_functions.php:410, include/do_search.php:126'),
    array('id' => 'J4', 'type' => 'Posted special search prefix, more terms', 'search' => '!contributions9,title:park, sculpture', 'core' => 'Only what follows the first space is kept: sculpture applies, title:park is lost.', 'where' => 'include/do_search.php:126'),
    array('id' => 'J5', 'type' => 'Range with a start year only', 'search' => 'date:rangestart2024', 'core' => 'The form sends the year unpadded: name >= "2024", so everything from 2024 on.', 'where' => 'include/search_functions.php:3348, include/do_search_keywords.php:193'),
    array('id' => 'J6', 'type' => 'Range with months only', 'search' => 'date:rangestart2024-05end2024-06-31', 'core' => 'Start month unpadded, end month padded with 31: May and June 2024.', 'where' => 'include/search_functions.php:3348'),
