    array('id' => 'J11', 'type' => 'Property filter with terms', 'search' => '!propertiesfext:jpg ,sculpture, title:park', 'core' => 'The form\'s separator is a space then a comma; the comma is dropped and the terms apply.', 'where' => 'include/search_functions.php:406'),
    array('id' => 'J12', 'type' => 'Full-text box with a word', 'search' => 'sculpture, "@FULL_TEXT:distant island"', 'core' => 'The full-text term is appended with a space and then normalised into the comma list.', 'where' => 'include/search_functions.php:242'),
    array('id' => 'J13', 'type' => 'Date value and range on one field', 'search' => 'date:2024-05, date:rangestart2024-05-01end2024-05-31', 'core' => 'The date boxes and the range boxes are separate inputs, so both terms are sent: two joins, ANDed.', 'where' => 'include/search_functions.php:3289'),

    array('group' => 'K', 'title' => 'What the indexing flags control', 'intro' => 'Only the values of fields flagged for indexing become keywords, so the flag governs every form that goes through the keyword table: plain words, field words, phrases, OR, NOT and the short-wildcard LIKE branch. It does not govern full-text and other wildcards, which read node names, nor date and number terms, fixed-list options by name, @@ tokens, !hasdata and !empty, which all read nodes. Partial indexing adds every fragment of three or more letters as a keyword at the word\'s position. Complete indexing stores the whole value as one keyword, never split, so a value with spaces cannot be typed as a word. An inactive field, or one hidden from the user, is dropped from every union, wildcards included. Only the first 500 characters of a value become keywords ($node_keyword_index_chars). The advanced search form lists indexed fields only; the simple bar needs indexed or fixed-list. See also B12, B13, B19, C8, C9, D22, D23, F43 and B14.'),
    array('id' => 'K1', 'type' => 'Word that exists only in a non-indexed field', 'search' => 'nikon', 'core' => 'Not a keyword: nothing (the value is in the camera field, not flagged for indexing).', 'where' => 'include/do_search_keywords.php:387, include/resource_functions.php:7840'),
    array('id' => 'K2', 'type' => 'The same word with a wildcard', 'search' => 'nikon*', 'core' => 'The full-text branch reads node names of every visible field, indexed or not: the camera values match.', 'where' => 'include/do_search_keywords.php:617'),
    array('id' => 'K3', 'type' => 'Wildcard inside the non-indexed field', 'search' => 'camera:nik*', 'core' => 'Full-text restricted to the field: matches, although camera:nikon (B12) does not.', 'where' => 'include/do_search_keywords.php:617'),
    array('id' => 'K4', 'type' => 'Full-text box on a non-indexed field', 'search' => '"@FULL_TEXT:nikon"', 'core' => 'MATCH over node names: matches.', 'where' => 'include/do_search_keywords.php:30'),
    array('id' => 'K5', 'type' => 'Bare fragment of a partially indexed field', 'search' => 'ksho', 'core' => 'Fragments are ordinary keywords, so the fragment matches outside the field term too (compare B14).', 'where' => 'include/search_functions.php:2270'),
    array('id' => 'K6', 'type' => 'Word in an inactive field', 'search' => 'description:sculpture', 'core' => 'The field is found by name but inactive fields count as hidden and are excluded from the union: nothing (E7 in the review).', 'where' => 'include/resource_functions.php:7871, include/do_search_keywords.php:511'),
    array('id' => 'K7', 'type' => 'Phrase held only in non-indexed fields', 'search' => '"library book"', 'core' => 'The phrase goes through keywords: nothing.', 'where' => 'include/do_search_keywords.php:758'),
    array('id' => 'K8', 'type' => 'The same phrase through full text', 'search' => '"@FULL_TEXT:[QUOTES]library book[QUOTES]"', 'core' => 'Node names are read: the active non-indexed field matches, the inactive one is excluded as hidden.', 'where' => 'include/do_search_keywords.php:30, include/do_search_keywords.php:40'),
    array('id' => 'K9', 'type' => 'Complete indexing', 'search' => 'field:two words', 'api' => false, 'core' => 'The whole value is one keyword; a typed search splits on spaces, so only a single-token value is reachable by word, and wildcards or full text otherwise. No complete-indexed field on the test system.', 'where' => 'include/node_functions.php:1082'),
